using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishArchitectureScene {
static string Root="Assets/Afrer_Seconds/05.Model/Environment/Architecture_Rebuilt";
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/Architecture_Rebuild_20261103"));
static Material M(string n)=>AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/"+n+".mat");
static void Box(Transform parent,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;var rr=g.GetComponent<Renderer>();rr.sharedMaterial=mat;rr.shadowCastingMode=ShadowCastingMode.Off;GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.BatchingStatic|StaticEditorFlags.ReflectionProbeStatic);}
static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;
static object C(Collider c)=>new{path=P(c.transform),type=c.GetType().Name,position=V(c.transform.position),rotation=V(c.transform.eulerAngles),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,boundsCenter=V(c.bounds.center),boundsSize=V(c.bounds.size)};
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var original=SceneManager.GetActiveScene().path;var scene=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B5_Isolation.unity",OpenSceneMode.Single);var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var before=all.SelectMany(t=>t.GetComponents<Collider>()).Select(C).ToArray();Directory.CreateDirectory(R+"/SceneBackup");string sceneFile=scene.path;if(!File.Exists(R+"/SceneBackup/Level_B5_Isolation.unity")){File.Copy(sceneFile,R+"/SceneBackup/Level_B5_Isolation.unity");File.Copy(sceneFile+".meta",R+"/SceneBackup/Level_B5_Isolation.unity.meta");}
string prefab=Root+"/Prefabs/ObservationRecess_VisualOnly.prefab";Directory.CreateDirectory(Root+"/Prefabs");AssetDatabase.Refresh();var bay=new GameObject("ObservationRecess_VisualOnly");var concrete=M("AS_Concrete");var steel=M("AS_PaintedSteel");var dark=M("AS_Seal");Box(bay.transform,"BackWall",new Vector3(0,2.075f,1.04f),new Vector3(2.8f,1.9f,.08f),concrete);Box(bay.transform,"SideLeft",new Vector3(-1.36f,2.075f,.54f),new Vector3(.08f,1.9f,.92f),steel);Box(bay.transform,"SideRight",new Vector3(1.36f,2.075f,.54f),new Vector3(.08f,1.9f,.92f),steel);Box(bay.transform,"Floor",new Vector3(0,1.165f,.54f),new Vector3(2.64f,.08f,.92f),steel);Box(bay.transform,"Ceiling",new Vector3(0,2.985f,.54f),new Vector3(2.64f,.08f,.92f),steel);Box(bay.transform,"BackEquipmentPanel",new Vector3(0,1.86f,.985f),new Vector3(1.5f,.7f,.03f),dark);Box(bay.transform,"InsetReadoutA",new Vector3(-.38f,1.91f,.965f),new Vector3(.5f,.32f,.01f),steel);Box(bay.transform,"InsetReadoutB",new Vector3(.38f,1.91f,.965f),new Vector3(.5f,.32f,.01f),steel);
var em=new Material(Shader.Find("Universal Render Pipeline/Lit"));string mp=Root+"/Materials/AS_ObservationLight.mat";var ex=AssetDatabase.LoadAssetAtPath<Material>(mp);if(ex)UnityEngine.Object.DestroyImmediate(em);else{AssetDatabase.CreateAsset(em,mp);ex=em;}ex.SetColor("_BaseColor",new Color(.7f,.8f,.8f));ex.SetColor("_EmissionColor",new Color(.25f,.35f,.35f));ex.EnableKeyword("_EMISSION");EditorUtility.SetDirty(ex);Box(bay.transform,"CeilingLightDiffuser",new Vector3(0,2.9f,.6f),new Vector3(.9f,.035f,.12f),ex);var asset=PrefabUtility.SaveAsPrefabAsset(bay,prefab);UnityEngine.Object.DestroyImmediate(bay);
int floors=0,windows=0;foreach(var t in all.Where(t=>t!=null&&t.name=="RebuiltArchitectureVisual").ToArray()){var model=t.GetComponentInChildren<MeshFilter>();if(model&&AssetDatabase.GetAssetPath(model.sharedMesh).Contains("Env_FloorSlab_4m")){var pos=t.localPosition;pos.y=.002f;t.localPosition=pos;PrefabUtility.RecordPrefabInstancePropertyModifications(t);floors++;}if(model&&AssetDatabase.GetAssetPath(model.sharedMesh).Contains("Env_ObservationWall_4m")){var source=t.parent;string n=source.name+"_ObservationRecess";var group=source.parent;var old=group.Find(n);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset,scene);g.name=n;g.transform.SetParent(group,false);g.transform.position=source.position;g.transform.rotation=source.rotation*Quaternion.Euler(0,180,0);windows++;}}
all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var after=all.SelectMany(t=>t.GetComponents<Collider>()).Select(C).ToArray();if(!JToken.DeepEquals(JToken.Parse(JsonConvert.SerializeObject(before)),JToken.Parse(JsonConvert.SerializeObject(after))))throw new Exception("Collider changed");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(R+"/scene_finish_facts.json",JsonConvert.SerializeObject(new{floorVisualOffsets=floors,observationRecesses=windows,existingCollidersPreserved=true,recessTriangles=9*12,newColliders=0},Formatting.Indented));EditorSceneManager.OpenScene(original,OpenSceneMode.Single);return "B5 floor 2mm visual offset and two closed observation recesses applied";}}


